INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400019, now(), now(), 'seed', '<h2>سياسة الخصوصية</h2><p>Riyadh Fashion Hub، شارع العليا، الرياض، هي المسؤولة عن معالجة بياناتك وفق نظام حماية البيانات الشخصية السعودي.</p><h3>البيانات التي نجمعها</h3><ul><li>الاسم ورقم الجوال وعنوان التوصيل</li><li>سجل الطلبات والمرتجعات والمقاسات المحفوظة</li><li>بيانات التصفح إن وافقت على كوكيز القياس</li></ul><h3>مدة الاحتفاظ</h3><p>سجلات الطلبات عشر سنوات وفق الالتزامات الضريبية، وبيانات الحساب ثلاث سنوات من آخر نشاط.</p><h3>حقوقك</h3><p>لك حق الاطلاع والتصحيح والحذف والاعتراض عبر <a href="mailto:privacy@riyadhfashionhub.sa">privacy@riyadhfashionhub.sa</a>، ويمكنك التقدم بشكوى إلى الهيئة السعودية للبيانات والذكاء الاصطناعي.</p>', 'سياسة الخصوصية', 'سياسة الخصوصية', null, null, null, null, 'ar', -40010, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400020, now(), now(), 'seed', '<h2>Privacy policy</h2><p>Riyadh Fashion Hub, Olaya Street, Riyadh, is the controller of your data under the Saudi Personal Data Protection Law.</p><h3>What we collect</h3><ul><li>Name, mobile number and delivery address</li><li>Order and return history, and saved sizes</li><li>Browsing data, if you accept measurement cookies</li></ul><h3>How long we keep it</h3><p>Order records are kept ten years under tax obligations; account data three years after your last activity.</p><h3>Your rights</h3><p>Access, rectification, erasure and objection can be exercised at <a href="mailto:privacy@riyadhfashionhub.sa">privacy@riyadhfashionhub.sa</a>. You may complain to SDAIA at any time.</p>', 'Privacy policy', 'Privacy policy', null, null, null, null, 'en', -40010, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.policy_version (id, store_merchant_id, content_id, version, status, effective_from, note, translations, published_at, published_by)
