INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400021, now(), now(), 'seed', '<h2>الاستبدال والاسترجاع</h2><p>ثلاثون يومًا من الاستلام، سواء اشتريت أونلاين أو من المعرض.</p><h3>الشروط</h3><ul><li>القطعة غير مستعملة وبطاقتها الأصلية مثبّتة</li><li>الملابس الداخلية والأقراط لا تُسترجع لأسباب صحية</li><li>الاسترجاع مجاني عبر شركة الشحن أو من أي معرض</li></ul><h3>الاسترداد</h3><p>خلال خمسة أيام عمل من وصول القطعة، بنفس وسيلة الدفع. القطع المعدَّلة على المقاس تُستبدل ولا تُسترد قيمتها.</p><p><em>النسخة الثانية — رفعنا المدة من أربعة عشر يومًا إلى ثلاثين، وأصبح الاسترجاع مجانيًا.</em></p>', 'سياسة الاستبدال والاسترجاع', 'سياسة الاستبدال والاسترجاع', null, null, null, null, 'ar', -40011, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400022, now(), now(), 'seed', '<h2>Returns & exchanges</h2><p>Thirty days from delivery, whether you bought online or in store.</p><h3>Conditions</h3><ul><li>Unworn, with the original tag still attached</li><li>Underwear and pierced earrings cannot be returned, for hygiene reasons</li><li>Returns are free, by carrier pickup or at any store</li></ul><h3>Refunds</h3><p>Within five working days of the item arriving, to the original payment method. Altered garments can be exchanged but not refunded.</p><p><em>Version 2 — the window went from fourteen days to thirty, and returns are now free.</em></p>', 'Returns & exchanges', 'Returns & exchanges', null, null, null, null, 'en', -40011, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.policy_version (id, store_merchant_id, content_id, version, status, effective_from, note, translations, published_at, published_by)
VALUES (-4002, '65f023632bc46470c104b76f', -40011, 1, 'ARCHIVED', now() - interval '400 days', 'Initial version', '[{"language": "ar", "title": "سياسة الاستبدال والاسترجاع", "body": "<h2>الاستبدال والاسترجاع</h2><p>أربعة عشر يومًا، ورسوم شحن الاسترجاع 25 ريالًا على العميل.</p><p><em>النسخة الأولى — مؤرشفة.</em></p>", "state": "TRANSLATED"}, {"language": "en", "title": "Returns & exchanges", "body": "<h2>Returns & exchanges</h2><p>Fourteen days, with a SAR 25 return shipping fee paid by the customer.</p><p><em>Version 1 — archived.</em></p>", "state": "TRANSLATED"}]', now(), 'seed')
on conflict (id) do nothing;
