INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400023, now(), now(), 'seed', '<h2>الشحن</h2><p>الطلبات المؤكدة قبل الساعة الثالثة عصرًا تُشحن في نفس اليوم من مستودع الخرج.</p><table><tr><th>الوجهة</th><th>المدة</th><th>التكلفة</th></tr><tr><td>الرياض</td><td>يوم واحد</td><td>مجانًا فوق 200 ريال</td></tr><tr><td>جدة والدمام ومكة</td><td>يومان إلى ثلاثة</td><td>25 ريالًا</td></tr><tr><td>باقي مناطق المملكة</td><td>ثلاثة إلى خمسة أيام</td><td>30 ريالًا</td></tr><tr><td>دول الخليج</td><td>خمسة إلى ثمانية أيام</td><td>75 ريالًا</td></tr></table><p>التوصيل داخل الرياض متاح في نفس اليوم للطلبات قبل الظهر مقابل 35 ريالًا.</p>', 'سياسة الشحن', 'سياسة الشحن', null, null, null, null, 'ar', -40012, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400024, now(), now(), 'seed', '<h2>Shipping</h2><p>Orders confirmed before 3pm ship the same day from the Al-Kharj warehouse.</p><table><tr><th>Destination</th><th>Time</th><th>Cost</th></tr><tr><td>Riyadh</td><td>1 day</td><td>Free over SAR 200</td></tr><tr><td>Jeddah, Dammam, Makkah</td><td>2–3 days</td><td>SAR 25</td></tr><tr><td>Rest of the Kingdom</td><td>3–5 days</td><td>SAR 30</td></tr><tr><td>GCC states</td><td>5–8 days</td><td>SAR 75</td></tr></table><p>Same-day delivery inside Riyadh is available for orders placed before noon, at SAR 35.</p>', 'Shipping policy', 'Shipping policy', null, null, null, null, 'en', -40012, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
