INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400025, now(), now(), 'seed', '<h2>ملفات تعريف الارتباط</h2><p>نستخدم ثلاث فئات، واحدة منها لا يمكن إيقافها لأن السلة تعتمد عليها.</p><ul><li><strong>أساسية</strong> — السلة والجلسة والأمان. تعمل دائمًا.</li><li><strong>قياس</strong> — إحصاءات مجمّعة، ثلاثة عشر شهرًا.</li><li><strong>تخصيص</strong> — اقتراح مقاسات وأنماط، ستة أشهر.</li></ul><p>يُحفظ اختيارك ستة أشهر ويمكن تعديله من رابط « تفضيلات الكوكيز » أسفل الصفحة.</p>', 'سياسة ملفات تعريف الارتباط', 'سياسة ملفات تعريف الارتباط', null, null, null, null, 'ar', -40013, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400026, now(), now(), 'seed', '<h2>Cookies</h2><p>Three families of cookies, one of which cannot be switched off because the cart depends on it.</p><ul><li><strong>Essential</strong> — cart, session, security. Always on.</li><li><strong>Measurement</strong> — aggregate statistics, 13 months.</li><li><strong>Personalisation</strong> — size and style suggestions, 6 months.</li></ul><p>Your choice is stored for six months and can be changed from the “Cookie preferences” link in the footer.</p>', 'Cookie policy', 'Cookie policy', null, null, null, null, 'en', -40013, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.policy_version (id, store_merchant_id, content_id, version, status, effective_from, note, translations, published_at, published_by)
VALUES (-4005, '65f023632bc46470c104b76f', -40013, 1, 'LIVE', now() - interval '30 days', null, '[{"language": "ar", "title": "سياسة ملفات تعريف الارتباط", "body": "<h2>ملفات تعريف الارتباط</h2><p>نستخدم ثلاث فئات، واحدة منها لا يمكن إيقافها لأن السلة تعتمد عليها.</p><ul><li><strong>أساسية</strong> — السلة والجلسة والأمان. تعمل دائمًا.</li><li><strong>قياس</strong> — إحصاءات مجمّعة، ثلاثة عشر شهرًا.</li><li><strong>تخصيص</strong> — اقتراح مقاسات وأنماط، ستة أشهر.</li></ul><p>يُحفظ اختيارك ستة أشهر ويمكن تعديله من رابط « تفضيلات الكوكيز » أسفل الصفحة.</p>", "state": "TRANSLATED"}, {"language": "en", "title": "Cookie policy", "body": "<h2>Cookies</h2><p>Three families of cookies, one of which cannot be switched off because the cart depends on it.</p><ul><li><strong>Essential</strong> — cart, session, security. Always on.</li><li><strong>Measurement</strong> — aggregate statistics, 13 months.</li><li><strong>Personalisation</strong> — size and style suggestions, 6 months.</li></ul><p>Your choice is stored for six months and can be changed from the “Cookie preferences” link in the footer.</p>", "state": "TRANSLATED"}]', now(), 'seed')
on conflict (id) do nothing;

